import type { WikiPage, WikiSection } from '../site-data';
import type { ContentBlock } from './types';

const p = (text: string): ContentBlock => ({ kind: 'paragraph', text });
const h = (text: string): ContentBlock => ({ kind: 'heading', text });
const fig = (name: string, alt: string, caption: string): Extract<ContentBlock, { kind: 'figure' }> => ({
  kind: 'figure',
  src: `/figures/hp/figure-${name}.webp`,
  alt,
  caption,
});
const assetFig = (src: string, alt: string, caption: string): Extract<ContentBlock, { kind: 'figure' }> => ({
  kind: 'figure',
  src,
  alt,
  caption,
});
const pdf = (src: string, label: string): Extract<ContentBlock, { kind: 'pdf' }> => ({
  kind: 'pdf',
  src,
  downloadSrc: src,
  label,
  downloadLabel: 'Download PDF',
});
const grid = (...figures: Extract<ContentBlock, { kind: 'figure' }>[]): ContentBlock => ({
  kind: 'figure-grid',
  figures: figures.map(({ src, alt, caption }) => ({ src, alt, caption })),
});
const section = (title: string, body: string, blocks: ContentBlock[] = [], items?: string[]): WikiSection => ({
  title,
  body,
  blocks,
  items,
});

